fn main() {
    // Example usage (outside of verification):
    let arr = Vec::from_slice(&[DType::Int32, DType::Float64, DType::UInt8]);
    let sc  = Vec::from_slice(&[DType::Int16]);
    let common = find_common_type(arr, sc);
    assert!(common.is_some());
    // common.unwrap() would be Float64 vs Int16 => different kinds => returns the scalar max => Int16
    assert!(common.unwrap() == DType::Int16);
}